use learn_claude_code_rust::{ApiRequest, ApiResponse, ContentBlock, Message};
use reqwest::Client;
use serde_json::{json, Value};
use std::io::{self, Write};

const MODEL: &str = "claude-haiku-4-5-20251001"; // 比 "claude-opus-4-6" 省钱,够用了
const MAX_TOKENS: u32 = 8096;
const SYSTEM: &str = "You are a helpful assistant.";

#[tokio::main]
async fn main () {
    let api_key = std::env::var("ANTHROPIC_API_KEY").expect("ANTHROPIC_API_KEY not set");
    let client = Client::new();
    let mut messages: Vec<Message> = vec![];

    println!("Agent ready. Type your message (Ctrl+C to exit):\n");

    loop {
        // 读取用户输入
        print!("> ");
        io::stdout().flush().unwrap();
        let mut input = String::new();
        io::stdin().read_line(&mut input).unwrap();
        let input = input.trim();
        if input.is_empty() {
            continue;
        }

        // 把用户消息加入历史
        messages.push(Message {
            role: "user".to_string(),
            content: json!(input),
        });

        // 调用 API
        let response = call_api(&client, &api_key, &messages).await;

        // 提取文本回复
        let reply = response.content.iter().filter_map(|block| match block {
            ContentBlock::Text { text } => Some(text.clone()),
            _ => None,
        })
        .collect::<Vec<_>>()
        .join("");

        println!("\nClaude: {}\n", reply);

        // 把 Claude 的回复加入历史
        messages.push(Message {
            role: "assistant".to_string(),
            content: json!(reply),
        });
    }
}

async fn call_api(client: &Client, api_key: &str, messages: &[Message]) -> ApiResponse {
    let request = ApiRequest {
        model: MODEL.to_string(),
        max_tokens: MAX_TOKENS,
        system: SYSTEM.to_string(),
        messages: messages.to_vec(),
        tools: None,
    };

    client
        /* .post("https://api.anthropic.com/v1/messages") */
        /* .header("x-api-key", api_key) */
        .post("https://api.ofox.ai/anthropic/v1/messages")
        .header("Authorization", format!("Bearer {}", api_key))
        .header("anthropic-version", "2023-06-01")
        .header("content-type", "application/json")
        .json(&request)
        .body(serde_json::to_string(&request).unwrap())
        .send()
        .await
        .unwrap()
        .json::<ApiResponse>()
        .await
        .unwrap()
}

use async_trait::async_trait;
use learn_claude_code_rust::Tool;
use serde_json::{json, Value};
use std::process::Command;

struct BashTool;

#[async_trait]
impl Tool for BashTool {
    fn name(&self) -> &str {
        "bash"
    }

    fn definition(&self) -> Value {
        json!({
            "name": "bash",
            "description": "Run a bash command",
            "input_schema": {
                "type": "object",
                "properties": {
                    "command": { "type": "string" }
                },
                "required": ["command"]
            }
        })
    }

    async fn execute(&self, input: Value) -> String {
        let command = input["command"].as_str().unwrap_or("");
        let output = Command::new("sh")
            .arg("-c")
            .arg(command)
            .output()
            .expect("failed to execute");
        String::from_utf8_lossy(&output.stdout).to_string()
            + &String::from_utf8_lossy(&output.stderr)
    }
}

struct ReadFileTool;

#[async_trait]
impl Tool for ReadFileTool {
    fn name(&self) -> &str {
        "read_file"
    }

    fn definition(&self) -> Value {
        json!({
            "name": "read_file",
            "description": "Read the contents of a file",
            "input_schema": {
                "type": "object",
                "properties": {
                    "path": { "type": "string" }
                },
                "required": ["path"]
            }
        })
    }

    async fn execute(&self, input: Value) -> String {
        let path = input["path"].as_str().unwrap_or("");
        std::fs::read_to_string(path).unwrap_or_else(|e| e.to_string())
    }
}

struct WriteFileTool;

#[async_trait]
impl Tool for WriteFileTool {
    fn name(&self) -> &str { "write_file" }

    fn definition(&self) -> Value {
        json!({
            "name": "write_file",
            "description": "Write content to a file",
            "input_schema": {
                "type": "object",
                "properties": {
                    "path": { "type": "string" },
                    "content": { "type": "string" }
                },
                "required": ["path", "content"]
            }
        })
    }

    async fn execute(&self, input: Value) -> String {
        let path = input["path"].as_str().unwrap_or("");
        let content = input["content"].as_str().unwrap_or("");
        std::fs::write(path, content).map(|_| "ok".to_string()).unwrap_or_else(|e| e.to_string())
    }
}

struct EditFileTool;

#[async_trait]
impl Tool for EditFileTool {
    fn name(&self) -> &str { "edit_file" }

    fn definition(&self) -> Value {
        json!({
            "name": "edit_file",
            "description": "Replace a string in a file",
            "input_schema": {
                "type": "object",
                "properties": {
                    "path": { "type": "string" },
                    "old_str": { "type": "string" },
                    "new_str": { "type": "string" }
                },
                "required": ["path", "old_str", "new_str"]
            }
        })
    }

    async fn execute(&self, input: Value) -> String {
        let path = input["path"].as_str().unwrap_or("");
        let old = input["old_str"].as_str().unwrap_or("");
        let new = input["new_str"].as_str().unwrap_or("");
        match std::fs::read_to_string(path) {
            Ok(text) => {
                let updated = text.replace(old, new);
                std::fs::write(path, updated).map(|_| "ok".to_string()).unwrap_or_else(|e| e.to_string())
            }
            Err(e) => e.to_string(),
        }
    }
}

use std::collections::HashMap;
use std::io::{Write, stdin, stdout};

#[tokio::main]
async fn main() {
    let api_key = std::env::var("ANTHROPIC_API_KEY").expect("ANTHROPIC_API_KEY not set");
    let client = reqwest::Client::new();

    // 构建 dispatcher
    let mut tools: HashMap<String, Box<dyn Tool>> = HashMap::new();
    tools.insert("bash".to_string(), Box::new(BashTool));
    tools.insert("read_file".to_string(), Box::new(ReadFileTool));
    tools.insert("write_file".to_string(), Box::new(WriteFileTool));
    tools.insert("edit_file".to_string(), Box::new(EditFileTool));

    let tool_defs: Vec<Value> = tools.values().map(|t| t.definition()).collect();

    // 读用户输入
    print!("> ");
    Write::flush(&mut stdout()).unwrap();
    let mut input = String::new();
    stdin().read_line(&mut input).unwrap();

    let mut messages = vec![learn_claude_code_rust::Message {
        role: "user".to_string(),
        content: serde_json::json!(input.trim()),
    }];

    // agent loop
    loop {
        let response = call_api(&client, &api_key, &messages, &tool_defs).await;

        if response.stop_reason.as_deref() == Some("tool_use") {
            // 1. 把 assistant 回复加入历史
            messages.push(learn_claude_code_rust::Message {
                role: "assistant".to_string(),
                content: serde_json::json!(response.content),
            });

            // 2. 执行所有 tool_use, 收集结果
            let mut tool_results = vec![];
            for block in &response.content {
                if let learn_claude_code_rust::ContentBlock::ToolUse { id, name, input } = block {
                    println!("[调用工具] {}", name);
                    let result = tools[name].execute(input.clone()).await;
                    tool_results.push(serde_json::json!({
                        "type": "tool_result",
                        "tool_use_id": id,
                        "content": result
                    }));
                }
            }

            // 3. 把工具结果作为 user 消息加入历史
            messages.push(learn_claude_code_rust::Message {
                role: "user".to_string(),
                content: serde_json::json!(tool_results),
            });
        } else {
            // end_turn, 打印文本回复
            for block in &response.content {
                if let learn_claude_code_rust::ContentBlock::Text { text } = block {
                    println!("\nClaude: {}", text);
                }
            }
            break;
        }
    }
}

async fn call_api(client: &reqwest::Client, api_key: &str, messages: &[learn_claude_code_rust::Message], tools: &[Value],) -> learn_claude_code_rust::ApiResponse {
    let request = learn_claude_code_rust::ApiRequest {
        model: "claude-haiku-4-5".to_string(),
        max_tokens: 8096,
        system: "You are a helpful assistant.".to_string(),
        messages: messages.to_vec(),
        tools: Some(tools.to_vec()),
    };

    client
        .post("https://api.ofox.ai/anthropic/v1/messages")
        .header("Authorization", format!("Bearer {}", api_key))
        .header("anthropic-version", "2023-06-01")
        .header("content-type", "application/json")
        .json(&request)
        .send()
        .await
        .unwrap()
        .json::<learn_claude_code_rust::ApiResponse>()
        .await
        .unwrap()
}

use async_trait::async_trait;
use learn_claude_code_rust::Tool;
use serde_json::{json, Value};
use std::collections::HashMap;
use std::io::{Write, stdin, stdout};
use std::process::Command;
use std::sync::{Arc, Mutex};

// --- 数据结构 ---

#[derive(Debug, Clone)]
struct TodoItem {
    id: u32,
    title: String,
    status: String,
}

struct TodoManager {
    todos: Vec<TodoItem>,
    next_id: u32,
}

impl TodoManager {
    fn new() -> Self {
        TodoManager { todos: vec![], next_id: 1 }
    }

    fn add(&mut self, title: &str) -> u32 {
        let id = self.next_id;
        self.todos.push(TodoItem { id, title: title.to_string(), status: "pending".to_string() });
        self.next_id += 1;
        id
    }

    fn list(&self) -> String {
        if self.todos.is_empty() { return " (暂无任务) ".to_string(); }
        self.todos.iter().map(|t| {
            let icon = match t.status.as_str() {
                "done" => "✅",
                "in_progress" => "🔄",
                _ => "⬜"
            };
            format!("{} [{}] {}", icon, t.id, t.title)
        })
        .collect::<Vec<_>>().join("\n")
    }

    fn update(&mut self, id: u32, status: &str) -> String {
        match self.todos.iter_mut().find(|t| t.id == id) {
            Some(todo) => { todo.status = status.to_string(); format!("任务 #{} -> {}", id, status) }
            None => format!("找不到任务 #{}", id),
        }
    }

    fn delete(&mut self, id: u32) -> String {
        let before = self.todos.len();
        self.todos.retain(|t| t.id != id);
        if self.todos.len() < before {
            format!("已删除 #{}", id)
        } else {
            format!("找不到 #{}", id)
        }
    }
}

// --- TodoWriteTool ---

struct TodoWriteTool {
    manager: Arc<Mutex<TodoManager>>,
}

#[async_trait]
impl Tool for TodoWriteTool {
    fn name(&self) -> &str { "todo_write" }

    fn definition(&self) -> Value {
        json!({
            "name": "todo_write",
            "description": "管理任务列表。执行多步骤任务时，必须先add所有子任务，再逐步执行并更新状态。",
            "input_schema": {
                "type": "object",
                "properties": {
                    "action": { "type": "string", "enum": ["add", "list", "update", "delete"] },
                    "title":  { "type": "string" },
                    "id":     { "type": "integer" },
                    "status": { "type": "string", "enum": ["pending", "in_progress", "done"] }
                },
                "required": ["action"]
            }
        })
    }

    async fn execute(&self, input: Value) -> String {
        let mut mgr = self.manager.lock().unwrap();
        match input["action"].as_str().unwrap_or("") {
            "add" => { let t = input["title"].as_str().unwrap_or("未命名"); format!("已添加 #{}: {}", mgr.add(t), t)}
            "list" => mgr.list(),
            "update" => mgr.update(input["id"].as_u64().unwrap_or(0) as u32, input["status"].as_str().unwrap_or("pending")),
            "delete" => mgr.delete(input["id"].as_u64().unwrap_or(0) as u32),
            other => format!("未知操作: {}", other),
        }
    }
}

