// agent loop

async fn agent_loop(
    client: &reqwest::Client,
    api_key: &str,
    system: &str,
    tools: &HashMap<String, Box<dyn Tool>>,
    tool_defs: &[Value],
    initial_message: &str,
) {
    let mut messages = vec![Message {
        role: "user".to_string(),
        content: json!(initial_message),
    }];

    loop {
        let response = call_api(client, api_key, &messages, tool_defs, system).await;

        match response.stop_reason.as_deref() {
            Some("tool_use") => {
                // 1. 把 assistant 的 tool_use 加入历史
                messages.push(Message {
                    role: "assistant".to_string(),
                    content: json!(response.content),
                });

                // 2. 执行每个工具，收集结果
                let mut results = vec![];
                for block in &response.content {
                    if let ContentBlock::ToolUse { id, name, input } = block {
                        println!("[工具调用] {}", name);
                        let result = tools[name].execute(input.clone()).await;
                        results.push(json!({
                            "type": "tool_result",
                            "tool_use_id": id,
                            "content": result
                        }));
                    }
                }

                // 3. 把 tool_result 加入历史，继续循环
                messages.push(Message {
                    role: "user".to_string(),
                    content: json!(results),
                });
            }
            _ => {
                // end_turn: 输出最终文本
                for block in &response.content {
                    if let ContentBlock::Text { text } = block {
                        println!("\nClaude: {}", text);
                    }
                }
                break;
            }
        }
    }
}

