#[tokio::main]
async fn main() {
    let api_key = std::env::var("ANTHROPIC_API_KEY").expect("ANTHROPIC_API_KEY not set");
    let client = reqwest::Client::new();

    let store: BgStore = Arc::new(Mutex::new(HashMap::new()));
    let (tx, mut rx) = mpsc::unbounded_channel::<(String, String, bool)>();
    let next_id = Arc::new(Mutex::new(1u32));

    let mut tools: HashMap<String, Box<dyn Tool>> = HashMap::new();
    tools.insert("run_background".to_string(), Box::new(RunBackgroundTool {
        store: store.clone(), tx, next_id,
    }));
    tools.insert("check_background".to_string(), Box::new(CheckBackgroundTool(store.clone())));
    tools.insert("list_background".to_string(),  Box::new(ListBackgroundTool(store.clone())));

    let tool_defs: Vec<Value> = tools.values().map(|t| t.definition()).collect();
    let system = "你是支持后台任务的 agent。用 run_background 启动耗时命令并告知用户任务 id；可继续对话；用 check_background 或 list_background 查询进度。";

    println!("=== S08 Background Tasks ===");
    println!("输入 exit 退出\n");

    let mut messages: Vec<learn_claude_code_rust::Message> = vec![];

    loop {
        // 非阻塞：打印所有已完成的后台通知
        while let Ok((id, out, err)) = rx.try_recv() {
            let label = if err { "失败" } else { "完成" };
            println!("\n[后台通知] {} {} | {}",
                id, label, out.lines().next().unwrap_or(""));
        }

        print!("> ");
        IoWrite::flush(&mut stdout()).unwrap();
        let mut line = String::new();
        stdin().read_line(&mut line).unwrap();
        let line = line.trim().to_string();
        if line.is_empty() { continue; }
        if line == "exit" || line == "quit" { break; }

        messages.push(learn_claude_code_rust::Message {
            role: "user".to_string(),
            content: json!(line),
        });

        // agent loop（工具调用直到 end_turn）
        loop {
            let resp = call_api(&client, &api_key, &messages, &tool_defs, system).await;

            if resp.stop_reason.as_deref() == Some("tool_use") {
                messages.push(learn_claude_code_rust::Message {
                    role: "assistant".to_string(),
                    content: json!(resp.content),
                });
                let mut results = vec![];
                for block in &resp.content {
                    if let learn_claude_code_rust::ContentBlock::ToolUse { id, name, input } = block {
                        println!("[工具] {}", name);
                        let result = match tools.get(name.as_str()) {
                            Some(t) => t.execute(input.clone()).await,
                            None => format!("未知工具: {}", name),
                        };
                        println!("    -> {}", result.lines().next().unwrap_or(""));
                        results.push(json!({
                            "type": "tool_result",
                            "tool_use_id": id,
                            "content": result
                        }));
                    }
                }
                messages.push(learn_claude_code_rust::Message {
                    role: "user".to_string(),
                    content: json!(results),
                });
            } else {
                println!();
                for block in &resp.content {
                    if let learn_claude_code_rust::ContentBlock::Text { text } = block {
                        println!("Claude: {}", text);
                    }
                }
                break;
            }
        }
    }
}

use async_trait::async_trait;
use learn_claude_code_rust::{ContentBlock, Message, Tool};
use serde_json::{json, Value};
use std::collections::HashMap;
use std::io::{Write as IoWrite, stdin, stdout};
use std::sync::Arc;

// --- Teammate 定义 ---

struct Teammate {
    name: String,
    role: String,
    system_prompt: String,
}

// --- 基础工具 (供 teammate 使用) ---

struct BashTool;
#[async_trait]
impl Tool for BashTool {
    fn name(&self) -> &str { "bash" }
    fn definition(&self) -> Value {
        json!({
            "name": "bash",
            "description": "执行 bash 命令",
            "input_schema": {
                "type": "object",
                "properties": { "command": { "type": "string" } },
                "required": ["command"]
            }
        })
    }
    async fn execute(&self, input: Value) -> String {
        let out = std::process::Command::new("sh")
            .arg("-c").arg(input["command"].as_str().unwrap_or(""))
            .output().expect("failed");
        String::from_utf8_lossy(&out.stdout).to_string()
            + &String::from_utf8_lossy(&out.stderr)
    }
}

// --- teammate 的 agent_loop ---
// 与 s04 的 agent_loop 一致，区别是接收 system_prompt 感受
// messages 是局部变量，完全隔离

async fn teammate_loop(
    client: &reqwest::Client,
    api_key: &str,
    system_prompt: &str,
    task: &str,
    tools: &HashMap<String, Box<dyn Tool>>,
    tool_defs: &[Value],
) -> String {
    let mut messages = vec![Message {
        role: "user".to_string(),
        content: json!(task),
    }];

    loop {
        let response = call_api(client, api_key, &messages, tool_defs, system_prompt).await;

        if response.stop_reason.as_deref() == Some("tool_use") {
            messages.push(Message {
                role: "assistant".to_string(),
                content: json!(response.content),
            });

            let mut results = vec![];
            for block in &response.content {
                if let ContentBlock::ToolUse { id, name, input } = block {
                    println!("  [teammate 工具] {}", name);
                    let result = tools[name].execute(input.clone()).await;
                    results.push(json!({
                        "type": "tool_result",
                        "tool_use_id": id,
                        "content": result
                    }));
                }
            }

            messages.push(Message {
                role: "user".to_string(),
                content: json!(results),
            });
        } else {
            return response.content.iter()
                .filter_map(|b| if let ContentBlock::Text { text } = b { Some(text.clone()) } else { None })
                .collect::<Vec<_>>()
                .join("\n");
        }
    }
}


// --- SendMessageTool ---
// 主 agent 用这个 tool 把任务发给指定的 teammate
// teammate 有自己的 role (system_prompt), 完全独立运行

struct SendMessageTool {
    client: Arc<reqwest::Client>,
    api_key: Arc<String>,
    // 用 Arc 共享 teammate 注册表
    teammates: Arc<HashMap<String, Teammate>>,
}

#[async_trait]
impl Tool for SendMessageTool {
    fn name(&self) -> &str { "send_message" }

    fn definition(&self) -> Value {
        json!({
            "name": "send_message",
            "description": "把任务发给指定的队友(teammate)。队友有自己的专长，会独立完成任务并返回结果。可用队友: coder(代码生成), reviewer(代码审查)",
            "input_schema": {
                "type": "object",
                "properties": {
                    "to": {
                        "type": "string",
                        "description": "队友名字: coder 或 reviewer"
                    },
                    "message": {
                        "type": "string",
                        "description": "交给队友的任务描述"
                    }
                },
                "required": ["to", "message"]
            }
        })
    }

    async fn execute(&self, input: Value) -> String {
        let to = input["to"].as_str().unwrap_or("");
        let message = input["message"].as_str().unwrap_or("");

        let Some(teammate) = self.teammates.get(to) else {
            return format!("未找到队友: {}", to);
        };

        println!("[主agent -> {}({})] {}", teammate.name, teammate.role, message);

        // teammate 的工具集 (根据角色可以不同，这里都给 bash)
        let mut tools: HashMap<String, Box<dyn Tool>> = HashMap::new();
        tools.insert("bash".to_string(), Box::new(BashTool));
        let tool_defs: Vec<Value> = tools.values().map(|t| t.definition()).collect();

        let result = teammate_loop(
            &self.client,
            &self.api_key,
            &teammate.system_prompt,
            message,
            &tools,
            &tool_defs,
        ).await;

        println!("[{} -> 主agent] 完成", teammate.name);
        result
    }
}

